/* ===================== BÀI 29 · Vector, enable và ưu tiên ===================== */
/* Bài 29 · Vector, enable và ưu tiên (AMTS-EMB-001-M08-L01, MC51-029) — sinh bởi tools/author/mcu8051/l29.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR29=[{"label":"Ví dụ: Main bị ngắt rồi chạy tiếp","code":"; Ví dụ 1: main bị ngắt rồi chạy tiếp (Timer 0)\n; Chip: AT89S52, 12 MHz. Cờ TF0 do phần mềm đặt để\n; thấy rõ lúc vào ngắt; LED ở P1 sáng khi chân = 0.\n        ORG     0000H\n        LJMP    MAIN                    ; nhảy qua bảng vectơ\n        ORG     000BH                   ; vectơ Timer 0\n        INC     30H                     ; ISR: đếm số lần vào ngắt\n        MOV     P1,#0FEH                ; LED P1.0 sáng: đã vào ISR\n        RETI                            ; trở về đúng chỗ bị ngắt\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        SETB    ET0                     ; cho phép riêng Timer 0\n        SETB    EA                      ; công tắc tổng\n        SETB    TF0                     ; giả lập Timer 0 tràn\n        MOV     A,#55H                  ; lệnh này chạy trước khi vào ISR\n        MOV     R7,A                    ; main chạy tiếp sau RETI\n        SJMP    $\n        END\n","note":"Bấm Từng bước tới lệnh SETB TF0 (chu kỳ 6). Đoán trước: lệnh kế tiếp có chạy trước khi vào ISR không? Có: MOV A,#55H chạy xong (chu kỳ 8) rồi phần cứng mới gọi ngắt, cất 003BH lên ngăn xếp ([08H] = 3BH, [09H] = 00H). Sau RETI, main chạy tiếp MOV R7,A; tổng 16 chu kỳ tới SJMP $.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Hai cờ cùng bật, thứ tự hỏi vòng","code":"; Ví dụ 2: hai cờ cùng bật, cùng mức ưu tiên\n; Thứ tự hỏi vòng: IE0, TF0, IE1, TF1, RI/TI, TF2\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH                   ; Timer 0 (hỏi vòng thứ 2)\n        MOV     @R0,#0BH                ; ghi vectơ vào bộ đệm\n        INC     R0\n        RETI\n        ORG     0013H                   ; INT1 (hỏi vòng thứ 3)\n        MOV     @R0,#13H\n        INC     R0\n        RETI\n        ORG     0030H\nMAIN:   MOV     R0,#40H                 ; R0 trỏ bộ đệm 40H, 41H\n        SETB    IT1                     ; INT1 kích sườn: IE1 giữ được\n        SETB    IE1                     ; bật hai cờ khi EA còn = 0\n        SETB    TF0\n        MOV     IE,#86H                 ; EA + EX1 + ET0\nCHO:    CJNE    R0,#42H,CHO             ; chờ hai ISR chạy xong\n        CLR     EA\n        SJMP    $\n        END\n","note":"Hai cờ IE1 và TF0 cùng chờ khi EA còn bằng 0. Sau MOV IE,#86H, CPU chạy thêm CJNE rồi vào Timer 0 trước (chu kỳ 10) vì TF0 đứng trước IE1 trong thứ tự hỏi vòng; xong RETI mới tới INT1 (chu kỳ 18). Bộ đệm: 40H = 0BH, 41H = 13H.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Ngắt lồng nhau","code":"; Ví dụ 3: ngắt lồng nhau\n; ISR Timer 0 (mức thấp) đang chạy thì INT0 (mức cao)\n; xin ngắt: CPU vào ISR INT0 ngay, xong mới quay lại.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H                   ; INT0, mức cao\n        MOV     @R0,#03H\n        INC     R0\n        RETI\n        ORG     000BH                   ; Timer 0, mức thấp\n        LJMP    T0ISR                   ; ISR dài: đặt ở chỗ khác\n        ORG     0030H\nMAIN:   MOV     R0,#40H\n        SETB    IT0                     ; INT0 kích sườn\n        SETB    PX0                     ; INT0 ưu tiên cao\n        MOV     IE,#83H                 ; EA + ET0 + EX0\n        SETB    TF0                     ; giả lập Timer 0 tràn\nCHO:    CJNE    R0,#43H,CHO             ; chờ đủ 3 dấu vết\n        CLR     EA\n        SJMP    $\nT0ISR:  MOV     @R0,#0BH                ; dấu vết: bắt đầu ISR Timer 0\n        INC     R0\n        SETB    IE0                     ; giả lập nút INT0 lúc này\n        NOP\n        NOP\n        MOV     @R0,#8BH                ; dấu vết: kết thúc ISR Timer 0\n        INC     R0\n        RETI\n        END\n","note":"ISR Timer 0 (mức thấp) tự đặt IE0 để giả lập nút INT0 được bấm giữa chừng. Sau một NOP, INT0 (mức cao) ngắt lồng ở chu kỳ 18: xem phần Ngăn xếp có hai địa chỉ trở về (003BH của main và 0048H trong ISR Timer 0). Bộ đệm 0BH, 03H, 8BH: ISR Timer 0 bị chen ngang rồi làm nốt.","dev":{"led":true},"fosc":12000000},{"label":"Lỗi: Kết thúc ISR bằng RET","code":"; Ví dụ 4 (LỖI): kết thúc ISR bằng RET thay cho RETI\n; RET lấy lại PC nhưng không báo \"đã xong ngắt\": CPU vẫn\n; coi như đang ở ISR mức thấp, chặn mọi ngắt mức thấp.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     30H\n        RET                             ; LỖI: phải là RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        MOV     IE,#82H                 ; EA + ET0\n        SETB    TF0                     ; lần 1: được phục vụ\n        NOP\n        NOP\n        SETB    TF0                     ; lần 2: bị chặn\n        NOP\n        NOP\n        CLR     EA\n        SJMP    $\n        END\n","note":"Lần SETB TF0 thứ nhất vào ISR bình thường. ISR kết thúc bằng RET nên phần cứng vẫn coi ISR mức thấp đang chạy: lần thứ hai TF0 bật (xem TCON = 20H lúc cuối) nhưng không bao giờ được phục vụ. Kết quả 30H = 01H thay vì 02H.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: Bật ET0 nhưng quên EA","code":"; Ví dụ 5 (BẪY): bật ET0 nhưng quên EA\n; IE.7 (EA) là công tắc tổng: EA = 0 thì mọi ngắt bị\n; khóa; cờ TF0 vẫn bật nhưng không ai phục vụ.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     30H\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        SETB    ET0                     ; chỉ bật riêng Timer 0\n        SETB    TF0                     ; cờ bật...\n        NOP\n        NOP                             ; ...nhưng không vào ngắt\n        SJMP    $\n        END\n","note":"ET0 = 1, TF0 = 1 nhưng EA = 0: không có lần vào ngắt nào, 30H giữ 00H, cờ TF0 vẫn bật (TCON = 20H). Thêm SETB EA trước SETB TF0 rồi chạy lại để so.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Độ trễ đáp ứng ngắt","code":"; Ví dụ 6: độ trễ đáp ứng phụ thuộc lệnh đang chạy\n; Lần 1: sau SETB TF0 là NOP (1 chu kỳ)\n; Lần 2: sau SETB TF0 là MUL AB (4 chu kỳ)\n        ORG     0000H\n        LJMP    MAIN\n        ORG     000BH\n        INC     30H\n        RETI\n        ORG     0030H\nMAIN:   MOV     30H,#0\n        MOV     IE,#82H                 ; EA + ET0\n        NOP\n        SETB    TF0                     ; lần 1\n        NOP                             ; lệnh đang chạy: 1 chu kỳ\n        NOP\n        SETB    TF0                     ; lần 2\n        MUL     AB                      ; lệnh đang chạy: 4 chu kỳ\n        NOP\n        CLR     EA\n        SJMP    $\n        END\n","note":"Lần 1: cờ bật ở cuối chu kỳ 8, lệnh đang chạy là NOP, phần cứng gọi ngắt ở chu kỳ 9, lệnh đầu của ISR bắt đầu ở chu kỳ 11: trễ 3 chu kỳ. Lần 2: cờ bật ở chu kỳ 16 nhưng MUL AB (4 chu kỳ) phải chạy xong, gọi ngắt ở chu kỳ 20, ISR bắt đầu ở 22: trễ 6 chu kỳ.","dev":{"led":true},"fosc":12000000}];
const sim29=makeSim51(document.getElementById("m51-l29"),{id:"s29",presets:PR29,ram:256});
makeEx51(document.getElementById("ex-l29"),"l29",[{"t":"Vectơ và byte IE của một nguồn ngắt","d":"<p>Ô <code>30H<\/code> chứa số thứ tự <i>n<\/i> của một nguồn ngắt AT89S52 theo bảng vectơ: 0 = INT0, 1 = Timer 0, 2 = INT1, 3 = Timer 1, 4 = cổng nối tiếp, 5 = Timer 2. Viết chương trình ghi vào <code>31H<\/code> byte thấp của địa chỉ vectơ (vectơ = 8<i>n<\/i> + 3) và ghi vào <code>32H<\/code> giá trị byte <code>IE<\/code> chỉ cho phép đúng nguồn <i>n<\/i> (bit <i>n<\/i> = 1, công tắc tổng EA = 1, các bit khác = 0). Không ghi vào IE thật. Ô <code>30H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 01H<\/code> (Timer 0) → <code>31H = 0BH<\/code>, <code>32H = 82H<\/code>.<\/p>","start":"; Bài 1: vectơ và byte IE của nguồn ngắt số n (30H)\n; Code mẫu: chạy được nhưng còn sai\n        ORG     0000H\n        MOV     A,30H                   ; A = n\n        RL      A\n        RL      A\n        RL      A                       ; A = 8n\n        MOV     31H,A                   ; còn thiếu gì?\n        MOV     A,#01H                  ; bit của nguồn n\n        MOV     R7,30H\n        INC     R7\n        SJMP    DEM\nQUAY:   RL      A\nDEM:    DJNZ    R7,QUAY\n        MOV     32H,A                   ; còn thiếu gì?\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1}},"expect":{"iram":{"0x30":1,"0x31":11,"0x32":130}}},{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x30":0,"0x31":3,"0x32":129}}},{"setup":{"iram":{"0x30":5}},"expect":{"iram":{"0x30":5,"0x31":43,"0x32":160}}},{"setup":{"iram":{"0x30":3}},"expect":{"iram":{"0x30":3,"0x31":27,"0x32":136}}},{"setup":{"iram":{"0x30":2}},"expect":{"iram":{"0x30":2,"0x31":19,"0x32":132}}},{"setup":{"iram":{"0x30":4}},"expect":{"iram":{"0x30":4,"0x31":35,"0x32":144}}}]},"hints":["Nhân 8 bằng ba lệnh RL A (n ≤ 5 nên không có bit nào bị quay vòng), rồi cộng 3.","Bit của nguồn n là 01H quay trái n lần. Code mẫu đã có vòng quay; xem nó còn thiếu bit nào của IE.","Còn một bit của IE phải bật thêm thì nguồn ngắt mới thật sự được phục vụ: bit nào?"],"why":"Bảng vectơ của họ 8051 cách đều 8 byte bắt đầu từ 0003H, nên vectơ = 8n + 3. Một nguồn chỉ được phục vụ khi cả bit riêng của nó và công tắc tổng EA đều bằng 1: byte IE = 80H OR (1 SHL n). Code mẫu quên + 3 và quên EA."},{"t":"ISR Timer 1 không phá dữ liệu của main","d":"<p>Phần MAIN của code mẫu (giữ nguyên) cho phép ngắt Timer 1, đặt <code>A = 5AH<\/code>, <code>CY = 1<\/code> rồi giả lập Timer 1 tràn <i>N<\/i> lần (<i>N<\/i> ở ô <code>30H<\/code>, 0–5) bằng <code>SETB TF1<\/code>. Mỗi lần vào ngắt, ISR phải cộng byte ở <code>31H<\/code> vào <code>40H<\/code> (8 bit, bỏ phần tràn) và tăng bộ đếm <code>41H<\/code>. Khi chương trình dừng ở <code>SJMP $<\/code>: <code>40H<\/code>, <code>41H<\/code> đúng và main vẫn thấy <code>A = 5AH<\/code>, <code>CY = 1<\/code>. Hãy sửa ISR.<\/p><p>Ví dụ: <code>30H = 3<\/code>, <code>31H = 10H<\/code> → <code>40H = 30H<\/code>, <code>41H = 03H<\/code>, <code>A = 5AH<\/code>, <code>CY = 1<\/code>.<\/p>","start":"; Bài 2: ISR Timer 1 cộng dồn và đếm, không phá main\n; Giữ nguyên phần MAIN; chỉ sửa ISR_T1.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     001BH                   ; vectơ Timer 1\n        LJMP    ISR_T1\n        ORG     0030H\nMAIN:   MOV     40H,#0\n        MOV     41H,#0\n        MOV     IE,#88H                 ; EA + ET1\n        MOV     R7,30H                  ; số lần giả lập Timer 1 tràn\n        INC     R7\n        MOV     A,#5AH                  ; main đang giữ A = 5AH\n        SETB    C                       ; và CY = 1\n        SJMP    DEM\nLAP:    SETB    TF1                     ; giả lập Timer 1 tràn\n        NOP\n        NOP\nDEM:    DJNZ    R7,LAP                  ; lặp N lần (N = 0: không lần nào)\n        CLR     EA\n        SJMP    $\nISR_T1: MOV     A,40H                   ; 40H = 40H + 31H\n        ADD     A,31H\n        MOV     40H,A\n        INC     41H                     ; đếm số lần vào ngắt\n        RETI\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":16}},"expect":{"iram":{"0x40":48,"0x41":3},"regs":{"A":90},"bits":{"CY":1}}},{"setup":{"iram":{"0x30":0,"0x31":34}},"expect":{"iram":{"0x40":0,"0x41":0},"regs":{"A":90},"bits":{"CY":1}}},{"setup":{"iram":{"0x30":1,"0x31":255}},"expect":{"iram":{"0x40":255,"0x41":1},"regs":{"A":90},"bits":{"CY":1}}},{"setup":{"iram":{"0x30":5,"0x31":64}},"expect":{"iram":{"0x40":64,"0x41":5},"regs":{"A":90},"bits":{"CY":1}}},{"setup":{"iram":{"0x30":2,"0x31":128}},"expect":{"iram":{"0x40":0,"0x41":2},"regs":{"A":90},"bits":{"CY":1}}},{"setup":{"iram":{"0x30":4,"0x31":1}},"expect":{"iram":{"0x40":4,"0x41":4},"regs":{"A":90},"bits":{"CY":1}}}]},"hints":["Chạy code mẫu từng bước: sau lần vào ngắt đầu tiên, A và CY của main còn đúng không?","ISR dùng A và lệnh ADD (đổi CY, AC, OV) nên phải cất ACC và PSW lên ngăn xếp ở đầu ISR.","Cất ở đầu ISR, lấy lại ngay trước RETI theo thứ tự ngược. PUSH/POP cần địa chỉ trực tiếp: viết ACC, không viết A."],"why":"Ngắt có thể đến giữa bất kỳ hai lệnh nào của main, nên ISR phải trả lại mọi thanh ghi nó dùng đúng như cũ. Lệnh ADD đổi cả A và PSW (CY, AC, OV); cất bằng PUSH ACC, PUSH PSW và lấy lại theo thứ tự ngược trước RETI. Bộ thử N = 0 là trường hợp biên: không lần ngắt nào, kết quả 0."},{"t":"Thứ tự theo IP, ISR ngắn nhất","d":"<p>Ô <code>30H<\/code> chứa giá trị cho thanh ghi <code>IP<\/code> (chỉ 4 bit thấp PX0, PT0, PX1, PT1 có thể bằng 1). Chương trình phải: đặt IP theo <code>30H<\/code>; cho INT0, INT1 kích sườn; bật cả bốn cờ <code>IE0<\/code>, <code>TF0<\/code>, <code>IE1<\/code>, <code>TF1<\/code> khi EA còn bằng 0; rồi cho phép cả bốn nguồn và EA. Mỗi ISR ghi byte thấp vectơ của mình (<code>03H<\/code>, <code>0BH<\/code>, <code>13H<\/code>, <code>1BH<\/code>) vào ô kế tiếp của bộ đệm bắt đầu ở <code>40H<\/code>. Khi đủ 4 lần ghi thì tắt EA và dừng ở <code>SJMP $<\/code>.<\/p><p>Code mẫu cho kết quả đúng nhưng chạy 88 chu kỳ máy và dài 79 byte. Hãy viết lại để chạy không quá <b>50 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>) và mã dài không quá <b>40 byte<\/b>.<\/p><p>Ví dụ: <code>30H = 00H<\/code> → <code>40H..43H = 03H 0BH 13H 1BH<\/code>; <code>30H = 08H<\/code> (PT1) → <code>1BH 03H 0BH 13H<\/code>.<\/p>","start":"; Bài 3: thứ tự phục vụ theo IP (30H), ISR ngắn\n; Code mẫu ĐÚNG KẾT QUẢ nhưng chậm và dài: hãy tối ưu.\n        ORG     0000H\n        LJMP    MAIN\n        ORG     0003H\n        LJMP    I_INT0\n        ORG     000BH\n        LJMP    I_T0\n        ORG     0013H\n        LJMP    I_INT1\n        ORG     001BH\n        LJMP    I_T1\n        ORG     0030H\nMAIN:   MOV     R0,#40H                 ; bộ đệm ghi thứ tự\n        MOV     A,30H\n        ANL     A,#0FH\n        MOV     IP,A\n        SETB    IT0                     ; kích sườn: cờ IE0, IE1 giữ được\n        SETB    IT1\n        SETB    IE0                     ; bật cả 4 cờ khi EA = 0\n        SETB    TF0\n        SETB    IE1\n        SETB    TF1\n        SETB    EX0\n        SETB    ET0\n        SETB    EX1\n        SETB    ET1\n        SETB    EA\nCHO:    CJNE    R0,#44H,CHO             ; chờ đủ 4 lần ghi\n        CLR     EA\n        SJMP    $\nI_INT0: PUSH    ACC\n        MOV     A,#03H\n        SJMP    GHI\nI_T0:   PUSH    ACC\n        MOV     A,#0BH\n        SJMP    GHI\nI_INT1: PUSH    ACC\n        MOV     A,#13H\n        SJMP    GHI\nI_T1:   PUSH    ACC\n        MOV     A,#1BH\nGHI:    MOV     @R0,A\n        INC     R0\n        POP     ACC\n        RETI\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":0}},"expect":{"iram":{"0x40":3,"0x41":11,"0x42":19,"0x43":27}}},{"setup":{"iram":{"0x30":8}},"expect":{"iram":{"0x40":27,"0x41":3,"0x42":11,"0x43":19}}},{"setup":{"iram":{"0x30":15}},"expect":{"iram":{"0x40":3,"0x41":11,"0x42":19,"0x43":27}}},{"setup":{"iram":{"0x30":5}},"expect":{"iram":{"0x40":3,"0x41":19,"0x42":11,"0x43":27}}},{"setup":{"iram":{"0x30":10}},"expect":{"iram":{"0x40":11,"0x41":27,"0x42":3,"0x43":19}}},{"setup":{"iram":{"0x30":4}},"expect":{"iram":{"0x40":19,"0x41":3,"0x42":11,"0x43":27}}}],"maxCyc":50,"maxBytes":40},"hints":["Mỗi ISR chỉ cần MOV @R0,#vectơ; INC R0; RETI = 4 byte: đặt thẳng vào ô vectơ (ô dài 8 byte), bỏ LJMP và PUSH/POP.","Bốn cờ và hai bit IT nằm chung trong TCON: một lệnh MOV TCON,#… thay cho sáu lệnh SETB. Tương tự một lệnh MOV IE,#… cho năm bit.","Vectơ 0000H cũng chỉ cần một lệnh nhảy ngắn tới phần chính đặt ngay sau ISR cuối; IP chép thẳng được từ ô RAM."],"why":"Khi nhiều cờ cùng chờ, CPU chọn nguồn mức cao trước, cùng mức thì theo thứ tự hỏi vòng IE0, TF0, IE1, TF1. ISR ngắn đặt ngay trong ô vectơ tiết kiệm 2 chu kỳ LJMP mỗi lần vào ngắt và PUSH/POP không cần vì ISR không đổi A. Lời giải mẫu: 46 chu kỳ, 36 byte."}]);

makeQuiz("quiz29","score29",[{"q": "Trên AT89S52, ISR của Timer 1 phải bắt đầu ở địa chỉ nào trong bộ nhớ chương trình?", "o": ["0013H", "001BH", "000BH", "0023H"], "a": 1, "e": "Timer 1 là nguồn số 3: vectơ = 8 × 3 + 3 = 27 = 001BH. 0013H là INT1, 000BH là Timer 0, 0023H là cổng nối tiếp."}, {"q": "Muốn chỉ cho phép ngắt Timer 0 và ngắt ngoài 1, cần ghi giá trị nào vào IE?", "o": ["06H", "82H", "8AH", "86H"], "a": 3, "e": "ET0 là IE.1 (02H), EX1 là IE.2 (04H), EA là IE.7 (80H): 80H + 04H + 02H = 86H. 06H quên EA nên không ngắt nào được phục vụ; 8AH là ET1 + ET0."}, {"q": "IP = 00H. Cờ TF1 và IE0 cùng bật khi EA = 0, sau đó chương trình bật EA (cả hai nguồn đã được cho phép). ISR nào chạy trước?", "o": ["Timer 1, vì cờ TF1 được bật trước", "Timer 1, vì timer luôn ưu tiên hơn ngắt ngoài", "INT0, vì IE0 đứng trước TF1 trong thứ tự hỏi vòng", "Cả hai chạy song song"], "a": 2, "e": "Cùng mức ưu tiên thì CPU chọn theo thứ tự hỏi vòng cố định IE0 → TF0 → IE1 → TF1 → RI/TI → TF2. Lúc cờ bật trước hay sau không quan trọng khi cả hai cùng chờ ở một lần hỏi vòng."}, {"q": "ISR của Timer 0 kết thúc bằng RET thay cho RETI. Điều gì xảy ra ở lần tràn kế tiếp của Timer 0 (mức thấp)?", "o": ["Không được phục vụ: phần cứng vẫn coi ISR mức thấp đang chạy", "Được phục vụ bình thường vì RET cũng lấy lại PC", "CPU tự reset", "Trình dịch báo lỗi vì ISR không có RETI"], "a": 0, "e": "RET chỉ lấy PC từ ngăn xếp. RETI còn báo cho logic ngắt rằng ISR ở mức này đã xong; thiếu nó, mọi yêu cầu cùng mức trở xuống bị chặn mãi (ví dụ 4). Trình dịch không biết đoạn nào là ISR nên không báo lỗi."}, {"q": "Cờ TF0 bật ở chu kỳ cuối của lệnh SETB TF0; lệnh kế tiếp là MUL AB (4 chu kỳ). Lệnh đầu của ISR bắt đầu sau bao nhiêu chu kỳ máy kể từ lúc cờ bật?", "o": ["3", "4", "2", "6"], "a": 3, "e": "MUL AB đã bắt đầu nên phải chạy xong 4 chu kỳ, cộng 2 chu kỳ của lệnh gọi do phần cứng: 6 chu kỳ (ví dụ 6). 3 chu kỳ là trường hợp lệnh kế tiếp chỉ dài 1 chu kỳ."}]);

